@startuml

class Product {
  + Name : string
  + Description : string
  + NetPrice : double
  + Manufacturer : string
  + CountryOfOrigin : string
}

class VATRate {
  + Rate : double
  + Currency : string
  + ConversionToEuro : double
}

class Representative {
  + FirstName : string
  + LastName : string
  + SSN : int
  + TelephoneNumber : string
  + EmailAddress : string
  + CountryRepresented : string
}

class Customer {
  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
  + CountriesReselling : string[]
}

class Order {
  + OrderID : int
  + Product : Product
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

Representative "1" -- "*" Customer
Product "1" -- "*" Order
Order "1" -- "1" Representative

@enduml

